7	
8	/*
9	 * Copy-first port of
10	 * node_modules/@salesforce/retail-react-app/app/pages/product-detail/index.jsx
11	 * (retail-react-app 10.0.0), converted to TypeScript per AGENTS.md's copy-first rule.
12	 *
13	 * The differences from the base file are the TypeScript annotations below, house
14	 * formatting, a small number of optional-chaining guards that strictNullChecks
15	 * requires — each flagged in place with a `Deviation from the base file` comment —
16	 * the relative `product-view` import, which is deliberate and explained at its
17	 * import site below, and SFCC-89's static product information: a `renderHeader`
18	 * implementation that replaces the base header's title/price block with the
19	 * Zimmermann content group, plus the meta block rendered below the accordions.
20	 * Both are marked `SFCC-89` in place.
21	 */
22	
23	import React, { Fragment, Suspense, useCallback, useEffect, useMemo, useRef, useState } from 'react';
24	import { Helmet } from 'react-helmet';
25	import { FormattedMessage, useIntl } from 'react-intl';
26	import { getUpdateBundleChildArray } from '@salesforce/retail-react-app/app/utils/product-utils';
27	
28	// Components
29	import { Box, Button, Skeleton, Stack, Heading } from '@salesforce/retail-react-app/app/components/shared/ui';
30	// SFCC-731 — replaces layerStyle="page" (base SFCC theme, symmetric padding + maxWidth on the
31	// whole page) so the hero section can bleed full-width per the confirmed Figma spec, while the
32	// rest of the page keeps the same containment layerStyle="page" used to provide. See this
33	// file's own render for the boxed={false}/boxed={true} split.
34	import PageContainer from '../../components/pageContainer';
35	// Imported directly from Chakra, not the shared/ui barrel: that barrel's useBreakpointValue
36	// re-export (shared/ui/useBreakpointValue/index.jsx) is an untyped .jsx passthrough, so a
37	// generic type argument on it fails to compile — same reasoning ui-kits files already use for
38	// importing hooks straight from '@chakra-ui/react' (see zimmDrawer/index.tsx).
39	import { useBreakpointValue } from '@chakra-ui/react';
40	import {
41	  useProduct,
42	  useProducts,
43	  useCategory,
44	  useShopperCustomersMutation,
45	  useShopperBasketsV2Mutation as useShopperBasketsMutation,
46	  useCustomerId,
47	  useShopperBasketsV2MutationHelper as useShopperBasketsMutationHelper,
48	} from '@salesforce/commerce-sdk-react';
49	
50	// Hooks
51	import { useCurrentBasket } from '@salesforce/retail-react-app/app/hooks/use-current-basket';
52	import { useVariant } from '@salesforce/retail-react-app/app/hooks';
53	import useNavigation from '@salesforce/retail-react-app/app/hooks/use-navigation';
54	import { useSafeHref } from 'app/hooks/useSafeHref';
55	import useEinstein from '@salesforce/retail-react-app/app/hooks/use-einstein';
56	import useDataCloud from '@salesforce/retail-react-app/app/hooks/use-datacloud';
57	import useActiveData from '@salesforce/retail-react-app/app/hooks/use-active-data';
58	import { useServerContext } from '@salesforce/pwa-kit-react-sdk/ssr/universal/hooks';
59	import usePickupShipment from '@salesforce/retail-react-app/app/hooks/use-pickup-shipment';
60	import { useSelectedStore } from '@salesforce/retail-react-app/app/hooks/use-selected-store';
61	import { useMultiship } from '@salesforce/retail-react-app/app/hooks/use-multiship';
62	import { getConfig } from '@salesforce/pwa-kit-runtime/utils/ssr-config';
63	import { useRecentlyViewedHistory } from '../../hooks/useRecentlyViewedHistory';
64	import { APP_MAIN_BLEED_MX } from '../../constants';
65	// Project Components
66	/*
67	 * Relative, not `@salesforce/retail-react-app/app/components/recommended-products`. Same
68	 * resolver behaviour as the ProductView import directly below: pwa-kit-dev's
69	 * OverridesResolverPlugin (isFromExtends) deliberately skips any request whose issuer already
70	 * lives in `overrides/` — see its own guard — so a base-path import from this file would resolve
71	 * to the *base*, unmodified component even in the real app build, not just in Storybook/Vitest.
72	 * Without this, none of PDP's three `<RecommendedProducts>` usages below (Complete-the-Set,
73	 * Might-Also-Like, and Recently Viewed) would ever reach the override, and SFCC-83's Recently
74	 * Viewed rail would silently never render on PDP (SFCC-83/84 build plan §2's 2026-09-06
75	 * correction). Cart needs no equivalent change — its own `recommended-products` import
76	 * (node_modules/@salesforce/retail-react-app/app/pages/cart/index.jsx) is issued from *outside*
77	 * `overrides/`, so the resolver already redirects it correctly today.
78	 */
79	import RecommendedProducts from '../../components/recommended-products';
80	/*
81	 * Relative, not `@salesforce/retail-react-app/app/components/product-view`. The overrides
82	 * resolver (pwa-kit-dev's OverridesResolverPlugin) deliberately skips any request whose
83	 * issuer already lives in `overrides/` — see its `isFromExtends` guard — so a base-path
84	 * import from this file resolves to the *base* component even in the real app build, not
85	 * just in Storybook/Vitest. Base callers (cart, wishlist, bonus-product) still reach our
86	 * override, because their issuer is inside node_modules and so is redirected normally.
87	 */
88	import ProductView, { SFCC_COLOUR_ATTRIBUTE_ID } from '../../components/product-view';
89	import type { ChildProductOrderability, ProductViewRefScope } from '../../components/product-view';
90	// SFCC-89 — static product information.
91	import { ZimmProductMeta } from '../../components/ui-kits/molecules/zimmProductMeta';
92	import { selectPdpProductInfo, buildRelatedSwatches, type RelatedSwatch } from './productInfo';
93	import { selectVariantScopedPriceData } from './variantScopedPrice';
94	import { StaticProductHeader } from './partials/staticProductHeader';
95	// Still used for product-set/bundle child cards below — that flow is out of scope for
96	// SFCC-736/195's Figma review (a plain single-product PDP hero column), so it is left as-is
97	// rather than folded into the new trigger-list/drawer treatment.
98	import InformationAccordion from '@salesforce/retail-react-app/app/pages/product-detail/partials/information-accordion';
99	import Island from '@salesforce/retail-react-app/app/components/island';
100	
101	// SFCC-736/195 — Details & Care drawer + PDP trigger links, replacing InformationAccordion for
102	// the standard (non-set/bundle) product path.
103	import { useModalState } from '../../hooks/use-modal-state';
104	import { ZimmDrawer } from '../../components/ui-kits/atoms/zimmDrawer';
105	import { ZimmPdpDrawer } from '../../components/ui-kits/organisms/zimmPdpDrawer';
106	import type { ZimmPdpDrawerTab } from '../../components/ui-kits/organisms/zimmPdpDrawer';
107	import type { ZimmDrawerSize } from '../../components/ui-kits/atoms/zimmDrawer';
108	import { PdpFooterLinks } from './partials/pdpFooterLinks';
109	import { DetailsAndCareContent } from './partials/detailsAndCareContent';
110	
111	import { HTTPNotFound, HTTPError } from '@salesforce/pwa-kit-react-sdk/ssr/universal/errors';
112	import logger from '@salesforce/retail-react-app/app/utils/logger-instance';
113	
114	// constant
115	import {
116	  API_ERROR_MESSAGE,
117	  EINSTEIN_RECOMMENDERS,
118	  MAX_CACHE_AGE,
119	  TOAST_ACTION_VIEW_WISHLIST,
120	  TOAST_MESSAGE_ADDED_TO_WISHLIST,
121	  TOAST_MESSAGE_ALREADY_IN_WISHLIST,
122	  STALE_WHILE_REVALIDATE,
123	} from '@salesforce/retail-react-app/app/constants';
124	// Zimmermann's own constant — NOT the base package above (see recommended-products/index.tsx's
125	// own comment on this exact gotcha: a named import off the base package's untyped module compiles
126	// but is undefined at runtime).
127	import { PAGE_CONTENT_BLEED_MX } from 'app/constants';
128	import { rebuildPathWithParams, productUrlBuilder } from '@salesforce/retail-react-app/app/utils/url';
129	import { useHistory, useLocation, useParams } from 'react-router-dom';
130	import { useToast } from '@salesforce/retail-react-app/app/hooks/use-toast';
131	import { useWishList } from '@salesforce/retail-react-app/app/hooks/use-wish-list';
132	import { useStoreLocatorModal } from '@salesforce/retail-react-app/app/hooks/use-store-locator';
133	import { isPickupMethod } from '@salesforce/retail-react-app/app/utils/shipment-utils';
134	import { useProductInventory } from '@salesforce/retail-react-app/app/hooks/use-product-inventory';
135	
136	// SFCC-91 — colour swatches (rendered inside ProductView via renderVariationAttribute).
137	// Lazy-loaded so the swatch group's chunk is deferred until React renders it, keeping it
138	// off the critical path for LCP.
139	const ZimmColourSwatchGroup = React.lazy(() => import('../../components/ui-kits/molecules/zimmColourSwatchGroup'));
140	
141	/** Frontend-enforced limit (SFCC-196). SFCC has no platform max-order-quantity field. */
142	const MAX_PURCHASE_QUANTITY = 3;
143	
144	/*
145	 * `@salesforce/retail-react-app` ships no TypeScript types (see
146	 * overrides/app/types/vendor.d.ts, which falls back to an untyped catch-all for its
147	 * subpaths), so the product / variant / category values this page threads between base
148	 * hooks and base components have no compile-time shape *from that package*. But the shapes
149	 * themselves are `commerce-sdk-isomorphic`'s, and it does export them as
150	 * `ShopperProductsTypes.Product` / `.Variant` / `.Category` — so these aliases are a
151	 * deliberate temporary gap, not proof that no type is available, and AGENTS.md's Type
152	 * Definitions rule says to import those directly. Deferred to a follow-up only because the
153	 * substitution also clears three `no-explicit-any` warnings, moving a lint count this branch
154	 * holds as an invariant. See the same note in `components/product-view/index.tsx`.
155	 */
156	type SfccProduct = any;
157	type SfccVariant = any;
158	type SfccCategory = any;
159	
160	/*
161	 * `@salesforce/commerce-sdk-react` types its query/mutation `parameters` more narrowly than
162	 * the base JS page satisfies (it types several always-present values as optional, and takes
163	 * `ids` as an array where the base joins them itself). The casts marked "SDK param widening"
164	 * below exist only to reconcile that; each passes exactly the value the base file passes, so
165	 * none of them changes runtime behaviour.
166	 */
167	
168	/** A basket line item as this page assembles it before handing it to the baskets API. */
169	type BasketLineItem = {
170	  productId?: string;
171	  id?: string;
172	  price?: number;
173	  quantity?: number;
174	  inventoryId?: string;
175	  shipmentId?: string;
176	  bundledProductItems?: Array<{ productId?: string; quantity?: number }>;
177	};
178	
179	/** A child product selection within a product set or bundle. */
180	type ChildProductSelection = {
181	  product?: SfccProduct;
182	  variant?: SfccVariant;
183	  quantity?: number;
184	};
185	
186	/** The imperative handle ProductView exposes for set/bundle child validation. */
187	type ChildProductRef = {
188	  ref: HTMLDivElement | null;
189	  validateOrderability: ProductViewRefScope['validateOrderability'];
190	};
191	
192	/** One row of the array the base ProductView passes to `addToCart`. */
193	type ProductSelectionValue = {
194	  product?: SfccProduct;
195	  variant?: SfccVariant;
196	  quantity?: number;
197	};
198	
199	/**
200	 * Errors thrown by the commerce SDK carry the originating `Response`, which the base
201	 * page reads to map an API status onto an SSR-visible HTTP error.
202	 */
203	type CommerceApiError = Error & { response?: { status?: number } };
204	
205	/** One value of a colour variation attribute as SFCC shapes it on the `values` array. */
206	type SfccSwatchAttrValue = {
207	  value?: string;
208	  name?: string;
209	  image?: { disBaseLink?: string; link?: string };
210	  href?: string;
211	  orderable?: boolean;
212	};
213	
214	const ProductDetail = () => {
215	  // react-intl returns already-bound methods, so destructuring them cannot unbind anything —
216	  // the rule cannot see that. `formatNumber` is SFCC-89's addition; the base file destructures
217	  // `formatMessage` alone. It feeds `formatPrice` below.
218	  // eslint-disable-next-line @typescript-eslint/unbound-method
219	  const { formatMessage, formatNumber } = useIntl();
220	  const history = useHistory();
221	  const location = useLocation();
222	  const einstein = useEinstein();
223	  const dataCloud = useDataCloud();
224	  const activeData = useActiveData();
225	  const toast = useToast();
226	  const navigate = useNavigation();
227	  const buildHref = useSafeHref();
228	  const customerId = useCustomerId();
229	  const { onOpen: onOpenStoreLocator } = useStoreLocatorModal();
230	  const multishipEnabled = getConfig()?.app?.multishipEnabled ?? true;
231	
232	  /****************************** Basket *********************************/
233	  const { data: basket, isLoading: isBasketLoading } = useCurrentBasket();
234	  const { addItemToNewOrExistingBasket } = useShopperBasketsMutationHelper();
235	  const updateItemsInBasketMutation = useShopperBasketsMutation('updateItemsInBasket');
236	  const { res } = useServerContext();
237	  if (res) {
238	    res.set('Cache-Control', `s-maxage=${MAX_CACHE_AGE}, stale-while-revalidate=${STALE_WHILE_REVALIDATE}`);
239	  }
240	
241	  /*************************** Pick up in Store ********************/
242	  const { selectedStore } = useSelectedStore();
243	  const selectedInventoryId = selectedStore?.inventoryId || null;
244	
245	  const { addInventoryIdsToPickupItems, updateDefaultShipmentIfNeeded, hasPickupItems } = usePickupShipment(basket);
246	
247	  /*************************** Multiship ********************/
248	  const { getShipmentIdForItems } = useMultiship(basket);
249	
250	  /*************************** Product Detail and Category ********************/
251	  const { productId } = useParams<{ productId?: string }>();
252	  const urlParams = new URLSearchParams(location.search);
253	  // SDK param widening — this component only mounts on `/product/:productId`, so one of the
254	  // two is always present. `useParams` types every segment optional by design — see the
255	  // comment on the react-router-dom shim in overrides/app/types/vendor.d.ts.
256	  const requestedProductId = (urlParams.get('pid') || productId) as string;
257	  const {
258	    data: productResponse,
259	    isLoading: isProductLoading,
260	    isError: isProductError,
261	    error: productError,
262	  } = useProduct(
263	    {
264	      parameters: {
265	        id: requestedProductId,
266	        perPricebook: true,
267	        expand: [
268	          'availability',
269	          'promotions',
270	          'options',
271	          'images',
272	          'prices',
273	          'variations',
274	          'set_products',
275	          'bundled_products',
276	          'page_meta_tags',
277	        ],
278	        allImages: true,
279	        ...(selectedInventoryId ? { inventoryIds: selectedInventoryId } : {}),
280	      },
281	    },
282	    {
283	      // When shoppers select a different variant (and the app fetches the new data),
284	      // the old data is still rendered (and not the skeletons).
285	      //
286	      // Load-bearing for accessibility, beyond the loading behaviour it was added for. The price
287	      // carries `aria-live` (zimmProductPrice), and a live region only announces a change if the
288	      // region already existed — a region inserted together with its content is silent. Keeping
289	      // the previous data means `ZimmProductContent` (rendered by the `StaticProductHeader`
290	      // partial) never unmounts on a variant change, so the price element survives and React
291	      // mutates its text in place, which is what gets announced.
292	      // Remove this option and the region is destroyed and rebuilt on every swatch click, and the
293	      // price stops being announced (WCAG 2.2 AA 4.1.3). No gate catches that: the atom's own test
294	      // renders it directly, and axe sees a well-formed region either way.
295	      keepPreviousData: true,
296	    },
297	  );
298	
299	  // Note: Since category needs id from product detail, it can't be server side rendered atm
300	  // until we can do dependent query on server
301	  const {
302	    data: category,
303	    isError: isCategoryError,
304	    error: categoryError,
305	  } = useCategory({
306	    parameters: {
307	      // SDK param widening — `useCategory` is a no-op until the product resolves, exactly as
308	      // in the base file.
309	      id: productResponse?.primaryCategoryId as string,
310	      levels: 1,
311	    },
312	  });
313	
314	  /****************************** Colour Swatches (SFCC-91) ***********************/
315	  // urlColour is the query-string colour param, read on every render so it is always current.
316	  // It is the only signal the ZimmColourSwatchGroup molecule needs — the atom navigates via
317	  // <Link to={href}>, updating the URL, and useDerivedProduct inside ProductView picks it up.
318	  const urlColour = new URLSearchParams(location.search).get(SFCC_COLOUR_ATTRIBUTE_ID) ?? undefined;
319	
320	  /****************************** Sets and Bundles *********************************/
321	  const [childProductSelection, setChildProductSelection] = useState<Record<string, ChildProductSelection>>({});
322	  const [childProductOrderability, setChildProductOrderability] = useState<Record<string, ChildProductOrderability>>(
323	    {},
324	  );
325	  const [selectedBundleQuantity, setSelectedBundleQuantity] = useState(1);
326	  const childProductRefs = React.useRef<Record<string, ChildProductRef>>({});
327	  // Deviation from the base file: `?.` on `type`. The base reads `productResponse?.type.set`,
328	  // which throws if the API ever returns a product without `type` (the SDK types it optional).
329	  // The two only differ in that already-broken case.
330	  const isProductASet = productResponse?.type?.set;
331	  const isProductABundle = productResponse?.type?.bundle;
332	
333	  const childVariantIds =
334	    isProductABundle || isProductASet
335	      ? Object.keys(childProductSelection)?.map(
336	          (key) => childProductSelection[key].variant?.productId || childProductSelection[key].product?.id,
337	        )
338	      : [];
339	
340	  const { data: variantProductData } = useProducts(
341	    {
342	      parameters: {
343	        // SDK param widening — the base file joins the ids itself and the SDK forwards the
344	        // value verbatim into the query string.
345	        ids: childVariantIds.join(',') as unknown as string[],
346	        allImages: false,
347	        ...(selectedInventoryId ? { inventoryIds: selectedInventoryId } : {}),
348	        expand: ['availability', 'variations'],
349	        select: '(data.(id,inventory,inventories,master))',
350	      },
351	    },
352	    {
353	      enabled: childVariantIds.length > 0,
354	      keepPreviousData: true,
355	    },
356	  );
357	
358	  const product: SfccProduct = useProductInventory(
359	    productResponse,
360	    variantProductData,
361	    selectedInventoryId,
362	    isProductASet,
363	    isProductABundle,
364	  );
365	
366	  /**************** Error Handling ****************/
367	
368	  if (isProductError) {
369	    const errorStatus = (productError as CommerceApiError | null)?.response?.status;
370	    switch (errorStatus) {
371	      case 404:
372	        throw new HTTPNotFound('Product Not Found.');
373	      default:
374	        throw new HTTPError(errorStatus, `HTTP Error ${errorStatus} occurred.`);
375	    }
376	  }
377	  if (isCategoryError) {
378	    const errorStatus = (categoryError as CommerceApiError | null)?.response?.status;
379	    switch (errorStatus) {
380	      case 404:
381	        throw new HTTPNotFound('Category Not Found.');
382	      default:
383	        throw new HTTPError(errorStatus, `HTTP Error ${errorStatus} occurred.`);
384	    }
385	  }
386	
387	  const [primaryCategory, setPrimaryCategory] = useState<SfccCategory>(category);
388	  const variant = useVariant(product);
389	
390	  // SFCC-194 — Was/Now sale price.
391	  //
392	  // Two URL states need correct priceData (mirrors feature/SFCC-194_pdp-was-now-sale-price):
393	  //
394	  //   Colour-only  → ?color=JJ8UTXX           (no pid; product is still the master)
395	  //   Colour+size  → ?color=JJ8UTXX&pid=…M    (pid present; product switches to standalone
396	  //                                              variant which lacks tieredPrices reliably)
397	  //
398	  // Strategy: keep the master product's variants[] as the authoritative tieredPrices source.
399	  // Filter them by pid (exact) or colour (set) from the URL, then call getPriceData on the
400	  // scoped result. This is overridden into renderHeader so the base ProductView's own
401	  // getPriceData call (which reads the standalone variant and loses tieredPrices) is bypassed.
402	  const masterProductRef = useRef<SfccProduct | null>(null);
403	  useEffect(() => {
404	    // Guard matches exactly what the memo reads from the cache: id (for the
405	    // cachedMasterMatchesCurrent check) and variants[] (for the filter). A partial SFCC
406	    // response that satisfies type.master but lacks either field is not useful — skip it
407	    // rather than writing a cache entry that would fall through to the deep-link fallback
408	    // one guard too late.
409	    if (productResponse?.type?.master && productResponse.id && productResponse.variants?.length) {
410	      masterProductRef.current = productResponse;
411	    }
412	  }, [productResponse]);
413	
414	  const urlPid = urlParams.get('pid') ?? undefined;
415	  const variantScopedPriceData = useMemo(
416	    () => selectVariantScopedPriceData(product, masterProductRef.current, urlPid, urlColour),
417	    // Re-runs when the fetched product changes (standalone variant arrives) or the URL
418	    // selection changes — both are signals the displayed price must update.
419	    // masterProductRef is a ref so it is intentionally absent from deps.
420	
421	    [urlPid, urlColour, product],
422	  );
423	
424	  // True while keepPreviousData holds stale product data during a variant re-fetch (size
425	  // selection). The fetched product id hasn't caught up with the URL yet, so any price
426	  // derived from the old product is unreliable — suppress it entirely until the fetch
427	  // settles rather than showing a briefly-incorrect Was/Now figure.
428	  const isPriceStale = requestedProductId !== product?.id;
429	
430	  // This page uses the `primaryCategoryId` to retrieve the category data. This attribute
431	  // is only available on `master` products. Since a variation will be loaded once all the
432	  // attributes are selected (to get the correct inventory values), the category information
433	  // is overridden. This will allow us to keep the initial category around until a different
434	  // master product is loaded.
435	  useEffect(() => {
436	    if (category) {
437	      setPrimaryCategory(category);
438	    }
439	  }, [category]);
440	
441	  /**************** Product Variant ****************/
442	  useEffect(() => {
443	    if (!variant) {
444	      return;
445	    }
446	    // update the variation attributes parameter on
447	    // the url accordingly as the variant changes
448	    const updatedUrl = rebuildPathWithParams(`${location.pathname}${location.search}`, {
449	      pid: variant?.productId,
450	    });
451	    history.replace(updatedUrl);
452	  }, [variant]);
453	
454	  /**************** Wishlist ****************/
455	  const { data: wishlist, isLoading: isWishlistLoading } = useWishList();
456	  const createCustomerProductListItem = useShopperCustomersMutation('createCustomerProductListItem');
457	
458	  // Derived at render time so ProductView can show the solid heart icon without needing
459	  // updateWishlist as a proxy. Matches the same check inside handleAddToWishlist.
460	  const isInWishlist = Boolean(
461	    wishlist?.customerProductListItems?.find(
462	      (i: { productId?: string }) => i.productId === variant?.productId || i.productId === product?.id,
463	    ),
464	  );
465	
466	  const handleAddToWishlist = (product: SfccProduct, variant: SfccVariant, quantity: number) => {
467	    const isItemInWishlist = wishlist?.customerProductListItems?.find(
468	      (i: { productId?: string }) => i.productId === variant?.productId || i.productId === product?.id,
469	    );
470	
471	    if (!isItemInWishlist) {
472	      createCustomerProductListItem.mutate(
473	        {
474	          parameters: {
475	            listId: wishlist.id,
476	            // SDK param widening — `useCustomerId` returns `string | null`; this branch is
477	            // only reachable once a wishlist has loaded, which requires a customer.
478	            customerId: customerId as string,
479	          },
480	          body: {
481	            // NOTE: API does not respect quantity, it always adds 1
482	            quantity,
483	            productId: variant?.productId || product?.id,
484	            public: false,
485	            priority: 1,
486	            type: 'product',
487	          },
488	        },
489	        {
490	          onSuccess: () => {
491	            toast({
492	              title: formatMessage(TOAST_MESSAGE_ADDED_TO_WISHLIST, { quantity: 1 }),
493	              status: 'success',
494	              action: (
495	                // it would be better if we could use <Button as={Link}>
496	                // but unfortunately the Link component is not compatible
