1039	                          // Assign the "set" scope of the ref, this is how we access the internal
1040	                          // validation.
1041	                          childProductRefs.current[childProduct.id] = {
1042	                            ref,
1043	                            validateOrderability: this.validateOrderability,
1044	                          };
1045	                        }}
1046	                        product={childProduct}
1047	                        isProductPartOfSet={isProductASet}
1048	                        isProductPartOfBundle={isProductABundle}
1049	                        childOfBundleQuantity={childQuantity}
1050	                        selectedBundleParentQuantity={selectedBundleQuantity}
1051	                        addToCart={
1052	                          isProductASet
1053	                            ? (productSelectionValues: ProductSelectionValue[]) =>
1054	                                handleAddToCart(productSelectionValues)
1055	                            : null
1056	                        }
1057	                        addToWishlist={isProductASet ? handleAddToWishlist : null}
1058	                        onVariantSelected={(product: SfccProduct, variant: SfccVariant, quantity: number) => {
1059	                          if (quantity) {
1060	                            setChildProductSelection((previousState) => ({
1061	                              ...previousState,
1062	                              [product.id]: {
1063	                                product,
1064	                                variant,
1065	                                quantity: isProductABundle ? childQuantity : quantity,
1066	                              },
1067	                            }));
1068	                          } else {
1069	                            const selections = {
1070	                              ...childProductSelection,
1071	                            };
1072	                            delete selections[product.id];
1073	                            setChildProductSelection(selections);
1074	                          }
1075	                        }}
1076	                        isProductLoading={isProductLoading}
1077	                        isBasketLoading={isBasketLoading}
1078	                        isWishlistLoading={isWishlistLoading}
1079	                        setChildProductOrderability={setChildProductOrderability}
1080	                        pickupInStore={!!pickupInStoreMap[childProductSelection[childProduct?.id]?.variant?.productId]}
1081	                        setPickupInStore={(checked: boolean) =>
1082	                          childProduct &&
1083	                          handlePickupInStoreChange(
1084	                            childProductSelection[childProduct?.id]?.variant?.productId,
1085	                            checked,
1086	                          )
1087	                        }
1088	                        onOpenStoreLocator={onOpenStoreLocator}
1089	                        showDeliveryOptions={false}
1090	                      />
1091	                      <InformationAccordion product={childProduct} />
1092	
1093	                      <Box display={['none', 'none', 'none', 'block']}>
1094	                        <hr />
1095	                      </Box>
1096	                    </Box>
1097	                  ),
1098	                )
1099	              }
1100	            </Fragment>
1101	          ) : (
1102	            <Fragment>
1103	              <Island hydrateOn={'visible'}>
1104	                <ProductView
1105	                  product={product}
1106	                  category={primaryCategory?.parentCategoryTree || []}
1107	                  renderVariationAttribute={(attr) => {
1108	                    if (attr.id !== SFCC_COLOUR_ATTRIBUTE_ID) return undefined;
1109	                    // When useDerivedProduct runs in controlled mode (size selected in local state),
1110	                    // SFCC's useVariationAttributes sets href:null on every value. We reconstruct
1111	                    // the href from the current URL — preserving existing params and swapping only
1112	                    // the colour — so swatches remain navigable after a size is picked.
1113	                    const values = (attr.values ?? []).map((v: SfccSwatchAttrValue) => {
1114	                      const params = new URLSearchParams(location.search);
1115	                      // Clear the size-variant pid so the new colour loads the master product,
1116	                      // not the previous colour's variant. Without this, requestedProductId
1117	                      // keeps fetching the old variant and the colour disagrees with what's shown.
1118	                      params.delete('pid');
1119	                      params.set(SFCC_COLOUR_ATTRIBUTE_ID, v.value ?? '');
1120	                      return {
1121	                        value: v.value ?? '',
1122	                        name: v.name ?? v.value ?? '',
1123	                        imageUrl: v.image?.disBaseLink || v.image?.link,
1124	                        href: `${location.pathname}?${params.toString()}`,
1125	                        orderable: v.orderable ?? true,
1126	                      };
1127	                    });
1128	
1129	                    // SFCC-708 — append related-colour swatches from the SCAPI-enriched
1130	                    // c_relatedSwatches field. The backend already filters out invalid and
1131	                    // offline products, so every item here is safe to render. Each swatch
1132	                    // links to a different master product via a full page reload (forceReload).
1133	                    // `c_relatedSwatches` is a Zimmermann SCAPI attribute absent from the SDK
1134	                    // types — the cast is safe because the backend guarantees this shape.
1135	                    const relatedSwatches = buildRelatedSwatches(
1136	                      (product?.c_relatedSwatches ?? []) as RelatedSwatch[],
1137	                      // Regional link prefixing fix (same class of bug as
1138	                      // productListCardMapper.ts's PLP href): productUrlBuilder alone has no
1139	                      // site/locale awareness, so its output is run through useSafeHref() before
1140	                      // buildRelatedSwatches appends the colour query param.
1141	                      (params) => buildHref(productUrlBuilder(params)),
1142	                      SFCC_COLOUR_ATTRIBUTE_ID,
1143	                    );
1144	                    const allValues = [...values, ...relatedSwatches];
1145	                    // Skeleton height approximates the rendered swatch group:
1146	                    // label row (var(--zimm-scale-xl) = 24px) + gap (8px) + swatch row (48px).
1147	                    return (
1148	                      <Suspense fallback={<Skeleton height="80px" />}>
1149	                        <ZimmColourSwatchGroup
1150	                          values={allValues}
1151	                          selectedValue={urlColour}
1152	                          label={attr.name ?? 'Colour'}
1153	                        />
1154	                      </Suspense>
1155	                    );
1156	                  }}
1157	                  renderHeader={(headerProps) => (
1158	                    <StaticProductHeader
1159	                      {...headerProps}
1160	                      priceData={isPriceStale ? null : variantScopedPriceData ?? headerProps.priceData}
1161	                      isPriceLoading={isPriceStale}
1162	                    />
1163	                  )}
1164	                  addToCart={handleAddToCart}
1165	                  addToWishlist={handleAddToWishlist}
1166	                  isInWishlist={isInWishlist}
1167	                  isProductLoading={isProductLoading}
1168	                  isBasketLoading={isBasketLoading}
1169	                  isWishlistLoading={isWishlistLoading}
1170	                  childProductOrderability={childProductOrderability}
1171	                  setChildProductOrderability={setChildProductOrderability}
1172	                  setSelectedBundleQuantity={setSelectedBundleQuantity}
1173	                  selectedBundleParentQuantity={selectedBundleQuantity}
1174	                  pickupInStore={!!pickupInStoreMap[product?.id]}
1175	                  setPickupInStore={(checked: boolean) => product && handlePickupInStoreChange(product.id, checked)}
1176	                  onOpenStoreLocator={onOpenStoreLocator}
1177	                  showDeliveryOptions={false}
1178	                  footerLinks={
1179	                    // `ZimmProductMeta` renders here, not in a separate Box below `<Island>` (where
1180	                    // `InformationAccordion` used to share one with it) — that positioned it as a
1181	                    // full-width block below the *whole* ProductView (both the image gallery and
1182	                    // info columns), so it rendered flush left instead of inside the info column,
1183	                    // a real bug Tim caught by comparing the running page against Figma. Its own
1184	                    // recipe (`zimmProductMeta.css.ts`'s `SPACE_META_ROW`/`paddingTop`) already
1185	                    // supplies the 28px gap from the trigger rows above it — nothing extra needed
1186	                    // here for that hop.
1187	                    <Box display="flex" flexDirection="column">
1188	                      <PdpFooterLinks
1189	                        triggers={pdpDrawerTabs.map(({ id, label }) => ({ id, label }))}
1190	                        onTriggerClick={openPdpDrawerAtTab}
1191	                        findInBoutiqueLabel={findInBoutiqueLabel}
1192	                        onFindInBoutiqueClick={openBoutiqueDrawer}
1193	                      />
1194	                      <ZimmProductMeta modelInfo={staticInfo?.modelInfo} styleCode={staticInfo?.styleCode} />
1195	                    </Box>
1196	                  }
1197	                  maxOrderQuantity={MAX_PURCHASE_QUANTITY}
1198	                  basketProductItems={basket?.productItems ?? []}
1199	                  showQuantityPicker={false}
1200	                  showStockMessage={false}
1201	                  showActionButtons={!product?.variationAttributes?.some((a: { id: string }) => a.id === 'size')}
1202	                  onFindYourSizeClick={() => openPdpDrawerAtTab('find-your-size')}
1203	                  onSizeGuideClick={() => openPdpDrawerAtTab('size-guide')}
1204	                />
1205	
1206	                <ZimmPdpDrawer
1207	                  key={activePdpTabId ?? 'closed'}
1208	                  isOpen={isPdpDrawerOpen}
1209	                  onClose={closePdpDrawer}
1210	                  size={pdpDrawerSize}
1211	                  tabs={pdpDrawerTabs}
1212	                  initialTabId={activePdpTabId ?? undefined}
1213	                  ariaLabel={pdpDrawerAriaLabel}
1214	                />
1215	                <ZimmDrawer
1216	                  isOpen={isBoutiqueDrawerOpen}
1217	                  onClose={closeBoutiqueDrawer}
1218	                  size="small"
1219	                  aria-label={findInBoutiqueLabel}
1220	                >
1221	                  <Box padding="var(--zimm-scale-xl)">{comingSoon}</Box>
1222	                </ZimmDrawer>
1223	              </Island>
1224	            </Fragment>
1225	          )}
1226	        </PageContainer>
1227	
1228	        {/* Product Recommendations — stays contained, same padding/maxWidth layerStyle="page"
1229	            provided before. */}
1230	        <PageContainer boxed={true}>
1231	          <Stack spacing={16}>
1232	            {!isProductASet && (
1233	              <Island hydrateOn={'visible'}>
1234	                <RecommendedProducts
1235	                  title={
1236	                    <FormattedMessage
1237	                      defaultMessage="Complete the Set"
1238	                      id="product_detail.recommended_products.title.complete_set"
1239	                    />
1240	                  }
1241	                  recommender={EINSTEIN_RECOMMENDERS.PDP_COMPLETE_SET}
1242	                  products={[product]}
1243	                  mx={PAGE_CONTENT_BLEED_MX}
1244	                  shouldFetch={() => product?.id}
1245	                />
1246	              </Island>
1247	            )}
1248	            <Island hydrateOn={'visible'}>
1249	              <RecommendedProducts
1250	                title={
1251	                  <FormattedMessage
1252	                    defaultMessage="You might also like"
1253	                    id="product_detail.recommended_products.title.might_also_like"
1254	                  />
1255	                }
1256	                recommender={EINSTEIN_RECOMMENDERS.PDP_MIGHT_ALSO_LIKE}
1257	                products={[product]}
1258	                mx={PAGE_CONTENT_BLEED_MX}
1259	                shouldFetch={() => product?.id}
1260	              />
1261	            </Island>
1262	
1263	            <Island hydrateOn={'visible'}>
1264	              <RecommendedProducts
1265	                // The Recently Viewed recommender doesn't use `products`, so instead we
1266	                // provide a key to update the recommendations on navigation.
1267	                key={location.key}
1268	                title={
1269	                  <FormattedMessage
1270	                    defaultMessage="Recently Viewed"
1271	                    id="product_detail.recommended_products.title.recently_viewed"
1272	                  />
1273	                }
1274	                recommender={EINSTEIN_RECOMMENDERS.PDP_RECENTLY_VIEWED}
1275	                mx={PAGE_CONTENT_BLEED_MX}
1276	              />
1277	            </Island>
1278	          </Stack>
1279	        </PageContainer>
1280	      </Stack>
1281	    </Box>
1282	  );
1283	};
1284	
1285	ProductDetail.getTemplateName = () => 'product-detail';
1286	
1287	/*
1288	 * The base file declares `ProductDetail.propTypes = {match: PropTypes.object}` purely as
1289	 * documentation — the component takes no props and never reads `match`. The TypeScript
