/*
 * Copyright (c) 2022, Salesforce, Inc.
 * All rights reserved.
 * SPDX-License-Identifier: BSD-3-Clause
 * For full license text, see the LICENSE file in the repo root or https://opensource.org/licenses/BSD-3-Clause
 */

/*
 * Copy-first port of
 * node_modules/@salesforce/retail-react-app/app/pages/product-detail/index.jsx
 * (retail-react-app 10.0.0), converted to TypeScript per AGENTS.md's copy-first rule.
 *
 * The differences from the base file are the TypeScript annotations below, house
 * formatting, a small number of optional-chaining guards that strictNullChecks
 * requires — each flagged in place with a `Deviation from the base file` comment —
 * the relative `product-view` import, which is deliberate and explained at its
 * import site below, and SFCC-89's static product information: a `renderHeader`
 * implementation that replaces the base header's title/price block with the
 * Zimmermann content group, plus the meta block rendered below the accordions.
 * Both are marked `SFCC-89` in place.
 */

import React, { Fragment, Suspense, useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { Helmet } from 'react-helmet';
import { FormattedMessage, useIntl } from 'react-intl';
import { getUpdateBundleChildArray } from '@salesforce/retail-react-app/app/utils/product-utils';

// Components
import { Box, Button, Skeleton, Stack, Heading } from '@salesforce/retail-react-app/app/components/shared/ui';
// SFCC-731 — replaces layerStyle="page" (base SFCC theme, symmetric padding + maxWidth on the
// whole page) so the hero section can bleed full-width per the confirmed Figma spec, while the
// rest of the page keeps the same containment layerStyle="page" used to provide. See this
// file's own render for the boxed={false}/boxed={true} split.
import PageContainer from '../../components/pageContainer';
// Imported directly from Chakra, not the shared/ui barrel: that barrel's useBreakpointValue
// re-export (shared/ui/useBreakpointValue/index.jsx) is an untyped .jsx passthrough, so a
// generic type argument on it fails to compile — same reasoning ui-kits files already use for
// importing hooks straight from '@chakra-ui/react' (see zimmDrawer/index.tsx).
import { useBreakpointValue } from '@chakra-ui/react';
import {
  useProduct,
  useProducts,
  useCategory,
  useShopperCustomersMutation,
  useShopperBasketsV2Mutation as useShopperBasketsMutation,
  useCustomerId,
  useShopperBasketsV2MutationHelper as useShopperBasketsMutationHelper,
} from '@salesforce/commerce-sdk-react';

// Hooks
import { useCurrentBasket } from '@salesforce/retail-react-app/app/hooks/use-current-basket';
import { useVariant } from '@salesforce/retail-react-app/app/hooks';
import useNavigation from '@salesforce/retail-react-app/app/hooks/use-navigation';
import { useSafeHref } from 'app/hooks/useSafeHref';
import useEinstein from '@salesforce/retail-react-app/app/hooks/use-einstein';
import useDataCloud from '@salesforce/retail-react-app/app/hooks/use-datacloud';
import useActiveData from '@salesforce/retail-react-app/app/hooks/use-active-data';
import { useServerContext } from '@salesforce/pwa-kit-react-sdk/ssr/universal/hooks';
import usePickupShipment from '@salesforce/retail-react-app/app/hooks/use-pickup-shipment';
import { useSelectedStore } from '@salesforce/retail-react-app/app/hooks/use-selected-store';
import { useMultiship } from '@salesforce/retail-react-app/app/hooks/use-multiship';
import { getConfig } from '@salesforce/pwa-kit-runtime/utils/ssr-config';
import { useRecentlyViewedHistory } from '../../hooks/useRecentlyViewedHistory';
import { APP_MAIN_BLEED_MX } from '../../constants';
// Project Components
/*
 * Relative, not `@salesforce/retail-react-app/app/components/recommended-products`. Same
 * resolver behaviour as the ProductView import directly below: pwa-kit-dev's
 * OverridesResolverPlugin (isFromExtends) deliberately skips any request whose issuer already
 * lives in `overrides/` — see its own guard — so a base-path import from this file would resolve
 * to the *base*, unmodified component even in the real app build, not just in Storybook/Vitest.
 * Without this, none of PDP's three `<RecommendedProducts>` usages below (Complete-the-Set,
 * Might-Also-Like, and Recently Viewed) would ever reach the override, and SFCC-83's Recently
 * Viewed rail would silently never render on PDP (SFCC-83/84 build plan §2's 2026-09-06
 * correction). Cart needs no equivalent change — its own `recommended-products` import
 * (node_modules/@salesforce/retail-react-app/app/pages/cart/index.jsx) is issued from *outside*
 * `overrides/`, so the resolver already redirects it correctly today.
 */
import RecommendedProducts from '../../components/recommended-products';
/*
 * Relative, not `@salesforce/retail-react-app/app/components/product-view`. The overrides
 * resolver (pwa-kit-dev's OverridesResolverPlugin) deliberately skips any request whose
 * issuer already lives in `overrides/` — see its `isFromExtends` guard — so a base-path
 * import from this file resolves to the *base* component even in the real app build, not
 * just in Storybook/Vitest. Base callers (cart, wishlist, bonus-product) still reach our
 * override, because their issuer is inside node_modules and so is redirected normally.
 */
import ProductView, { SFCC_COLOUR_ATTRIBUTE_ID } from '../../components/product-view';
import type { ChildProductOrderability, ProductViewRefScope } from '../../components/product-view';
// SFCC-89 — static product information.
import { ZimmProductMeta } from '../../components/ui-kits/molecules/zimmProductMeta';
import { selectPdpProductInfo, buildRelatedSwatches, type RelatedSwatch } from './productInfo';
import { selectVariantScopedPriceData } from './variantScopedPrice';
import { StaticProductHeader } from './partials/staticProductHeader';
// Still used for product-set/bundle child cards below — that flow is out of scope for
// SFCC-736/195's Figma review (a plain single-product PDP hero column), so it is left as-is
// rather than folded into the new trigger-list/drawer treatment.
import InformationAccordion from '@salesforce/retail-react-app/app/pages/product-detail/partials/information-accordion';
import Island from '@salesforce/retail-react-app/app/components/island';

// SFCC-736/195 — Details & Care drawer + PDP trigger links, replacing InformationAccordion for
// the standard (non-set/bundle) product path.
import { useModalState } from '../../hooks/use-modal-state';
import { ZimmDrawer } from '../../components/ui-kits/atoms/zimmDrawer';
import { ZimmPdpDrawer } from '../../components/ui-kits/organisms/zimmPdpDrawer';
import type { ZimmPdpDrawerTab } from '../../components/ui-kits/organisms/zimmPdpDrawer';
import type { ZimmDrawerSize } from '../../components/ui-kits/atoms/zimmDrawer';
import { PdpFooterLinks } from './partials/pdpFooterLinks';
import { DetailsAndCareContent } from './partials/detailsAndCareContent';

import { HTTPNotFound, HTTPError } from '@salesforce/pwa-kit-react-sdk/ssr/universal/errors';
import logger from '@salesforce/retail-react-app/app/utils/logger-instance';

// constant
import {
  API_ERROR_MESSAGE,
  EINSTEIN_RECOMMENDERS,
  MAX_CACHE_AGE,
  TOAST_ACTION_VIEW_WISHLIST,
  TOAST_MESSAGE_ADDED_TO_WISHLIST,
  TOAST_MESSAGE_ALREADY_IN_WISHLIST,
  STALE_WHILE_REVALIDATE,
} from '@salesforce/retail-react-app/app/constants';
// Zimmermann's own constant — NOT the base package above (see recommended-products/index.tsx's
// own comment on this exact gotcha: a named import off the base package's untyped module compiles
// but is undefined at runtime).
import { PAGE_CONTENT_BLEED_MX } from 'app/constants';
import { rebuildPathWithParams, productUrlBuilder } from '@salesforce/retail-react-app/app/utils/url';
import { useHistory, useLocation, useParams } from 'react-router-dom';
import { useToast } from '@salesforce/retail-react-app/app/hooks/use-toast';
import { useWishList } from '@salesforce/retail-react-app/app/hooks/use-wish-list';
import { useStoreLocatorModal } from '@salesforce/retail-react-app/app/hooks/use-store-locator';
import { isPickupMethod } from '@salesforce/retail-react-app/app/utils/shipment-utils';
import { useProductInventory } from '@salesforce/retail-react-app/app/hooks/use-product-inventory';

// SFCC-91 — colour swatches (rendered inside ProductView via renderVariationAttribute).
// Lazy-loaded so the swatch group's chunk is deferred until React renders it, keeping it
// off the critical path for LCP.
const ZimmColourSwatchGroup = React.lazy(() => import('../../components/ui-kits/molecules/zimmColourSwatchGroup'));

/** Frontend-enforced limit (SFCC-196). SFCC has no platform max-order-quantity field. */
const MAX_PURCHASE_QUANTITY = 3;

/*
 * `@salesforce/retail-react-app` ships no TypeScript types (see
 * overrides/app/types/vendor.d.ts, which falls back to an untyped catch-all for its
 * subpaths), so the product / variant / category values this page threads between base
 * hooks and base components have no compile-time shape *from that package*. But the shapes
 * themselves are `commerce-sdk-isomorphic`'s, and it does export them as
 * `ShopperProductsTypes.Product` / `.Variant` / `.Category` — so these aliases are a
 * deliberate temporary gap, not proof that no type is available, and AGENTS.md's Type
 * Definitions rule says to import those directly. Deferred to a follow-up only because the
 * substitution also clears three `no-explicit-any` warnings, moving a lint count this branch
 * holds as an invariant. See the same note in `components/product-view/index.tsx`.
 */
type SfccProduct = any;
type SfccVariant = any;
type SfccCategory = any;

/*
 * `@salesforce/commerce-sdk-react` types its query/mutation `parameters` more narrowly than
 * the base JS page satisfies (it types several always-present values as optional, and takes
 * `ids` as an array where the base joins them itself). The casts marked "SDK param widening"
 * below exist only to reconcile that; each passes exactly the value the base file passes, so
 * none of them changes runtime behaviour.
 */

/** A basket line item as this page assembles it before handing it to the baskets API. */
type BasketLineItem = {
  productId?: string;
  id?: string;
  price?: number;
  quantity?: number;
  inventoryId?: string;
  shipmentId?: string;
  bundledProductItems?: Array<{ productId?: string; quantity?: number }>;
};

/** A child product selection within a product set or bundle. */
type ChildProductSelection = {
  product?: SfccProduct;
  variant?: SfccVariant;
  quantity?: number;
};

/** The imperative handle ProductView exposes for set/bundle child validation. */
type ChildProductRef = {
  ref: HTMLDivElement | null;
  validateOrderability: ProductViewRefScope['validateOrderability'];
};

/** One row of the array the base ProductView passes to `addToCart`. */
type ProductSelectionValue = {
  product?: SfccProduct;
  variant?: SfccVariant;
  quantity?: number;
};

/**
 * Errors thrown by the commerce SDK carry the originating `Response`, which the base
 * page reads to map an API status onto an SSR-visible HTTP error.
 */
type CommerceApiError = Error & { response?: { status?: number } };

/** One value of a colour variation attribute as SFCC shapes it on the `values` array. */
type SfccSwatchAttrValue = {
  value?: string;
  name?: string;
  image?: { disBaseLink?: string; link?: string };
  href?: string;
  orderable?: boolean;
};

const ProductDetail = () => {
  // react-intl returns already-bound methods, so destructuring them cannot unbind anything —
  // the rule cannot see that. `formatNumber` is SFCC-89's addition; the base file destructures
  // `formatMessage` alone. It feeds `formatPrice` below.
  // eslint-disable-next-line @typescript-eslint/unbound-method
  const { formatMessage, formatNumber } = useIntl();
  const history = useHistory();
  const location = useLocation();
  const einstein = useEinstein();
  const dataCloud = useDataCloud();
  const activeData = useActiveData();
  const toast = useToast();
  const navigate = useNavigation();
  const buildHref = useSafeHref();
  const customerId = useCustomerId();
  const { onOpen: onOpenStoreLocator } = useStoreLocatorModal();
  const multishipEnabled = getConfig()?.app?.multishipEnabled ?? true;

  /****************************** Basket *********************************/
  const { data: basket, isLoading: isBasketLoading } = useCurrentBasket();
  const { addItemToNewOrExistingBasket } = useShopperBasketsMutationHelper();
  const updateItemsInBasketMutation = useShopperBasketsMutation('updateItemsInBasket');
  const { res } = useServerContext();
  if (res) {
    res.set('Cache-Control', `s-maxage=${MAX_CACHE_AGE}, stale-while-revalidate=${STALE_WHILE_REVALIDATE}`);
  }

  /*************************** Pick up in Store ********************/
  const { selectedStore } = useSelectedStore();
  const selectedInventoryId = selectedStore?.inventoryId || null;

  const { addInventoryIdsToPickupItems, updateDefaultShipmentIfNeeded, hasPickupItems } = usePickupShipment(basket);

  /*************************** Multiship ********************/
  const { getShipmentIdForItems } = useMultiship(basket);

  /*************************** Product Detail and Category ********************/
  const { productId } = useParams<{ productId?: string }>();
  const urlParams = new URLSearchParams(location.search);
  // SDK param widening — this component only mounts on `/product/:productId`, so one of the
  // two is always present. `useParams` types every segment optional by design — see the
  // comment on the react-router-dom shim in overrides/app/types/vendor.d.ts.
  const requestedProductId = (urlParams.get('pid') || productId) as string;
  const {
    data: productResponse,
    isLoading: isProductLoading,
    isError: isProductError,
    error: productError,
  } = useProduct(
    {
      parameters: {
        id: requestedProductId,
        perPricebook: true,
        expand: [
          'availability',
          'promotions',
          'options',
          'images',
          'prices',
          'variations',
          'set_products',
          'bundled_products',
          'page_meta_tags',
        ],
        allImages: true,
        ...(selectedInventoryId ? { inventoryIds: selectedInventoryId } : {}),
      },
    },
    {
      // When shoppers select a different variant (and the app fetches the new data),
      // the old data is still rendered (and not the skeletons).
      //
      // Load-bearing for accessibility, beyond the loading behaviour it was added for. The price
      // carries `aria-live` (zimmProductPrice), and a live region only announces a change if the
      // region already existed — a region inserted together with its content is silent. Keeping
      // the previous data means `ZimmProductContent` (rendered by the `StaticProductHeader`
      // partial) never unmounts on a variant change, so the price element survives and React
      // mutates its text in place, which is what gets announced.
      // Remove this option and the region is destroyed and rebuilt on every swatch click, and the
      // price stops being announced (WCAG 2.2 AA 4.1.3). No gate catches that: the atom's own test
      // renders it directly, and axe sees a well-formed region either way.
      keepPreviousData: true,
    },
  );

  // Note: Since category needs id from product detail, it can't be server side rendered atm
  // until we can do dependent query on server
  const {
    data: category,
    isError: isCategoryError,
    error: categoryError,
  } = useCategory({
    parameters: {
      // SDK param widening — `useCategory` is a no-op until the product resolves, exactly as
      // in the base file.
      id: productResponse?.primaryCategoryId as string,
      levels: 1,
    },
  });

  /****************************** Colour Swatches (SFCC-91) ***********************/
  // urlColour is the query-string colour param, read on every render so it is always current.
  // It is the only signal the ZimmColourSwatchGroup molecule needs — the atom navigates via
  // <Link to={href}>, updating the URL, and useDerivedProduct inside ProductView picks it up.
  const urlColour = new URLSearchParams(location.search).get(SFCC_COLOUR_ATTRIBUTE_ID) ?? undefined;

  /****************************** Sets and Bundles *********************************/
  const [childProductSelection, setChildProductSelection] = useState<Record<string, ChildProductSelection>>({});
  const [childProductOrderability, setChildProductOrderability] = useState<Record<string, ChildProductOrderability>>(
    {},
  );
  const [selectedBundleQuantity, setSelectedBundleQuantity] = useState(1);
  const childProductRefs = React.useRef<Record<string, ChildProductRef>>({});
  // Deviation from the base file: `?.` on `type`. The base reads `productResponse?.type.set`,
  // which throws if the API ever returns a product without `type` (the SDK types it optional).
  // The two only differ in that already-broken case.
  const isProductASet = productResponse?.type?.set;
  const isProductABundle = productResponse?.type?.bundle;

  const childVariantIds =
    isProductABundle || isProductASet
      ? Object.keys(childProductSelection)?.map(
          (key) => childProductSelection[key].variant?.productId || childProductSelection[key].product?.id,
        )
      : [];

  const { data: variantProductData } = useProducts(
    {
      parameters: {
        // SDK param widening — the base file joins the ids itself and the SDK forwards the
        // value verbatim into the query string.
        ids: childVariantIds.join(',') as unknown as string[],
        allImages: false,
        ...(selectedInventoryId ? { inventoryIds: selectedInventoryId } : {}),
        expand: ['availability', 'variations'],
        select: '(data.(id,inventory,inventories,master))',
      },
    },
    {
      enabled: childVariantIds.length > 0,
      keepPreviousData: true,
    },
  );

  const product: SfccProduct = useProductInventory(
    productResponse,
    variantProductData,
    selectedInventoryId,
    isProductASet,
    isProductABundle,
  );

  /**************** Error Handling ****************/

  if (isProductError) {
    const errorStatus = (productError as CommerceApiError | null)?.response?.status;
    switch (errorStatus) {
      case 404:
        throw new HTTPNotFound('Product Not Found.');
      default:
        throw new HTTPError(errorStatus, `HTTP Error ${errorStatus} occurred.`);
    }
  }
  if (isCategoryError) {
    const errorStatus = (categoryError as CommerceApiError | null)?.response?.status;
    switch (errorStatus) {
      case 404:
        throw new HTTPNotFound('Category Not Found.');
      default:
        throw new HTTPError(errorStatus, `HTTP Error ${errorStatus} occurred.`);
    }
  }

  const [primaryCategory, setPrimaryCategory] = useState<SfccCategory>(category);
  const variant = useVariant(product);

  // SFCC-194 — Was/Now sale price.
  //
  // Two URL states need correct priceData (mirrors feature/SFCC-194_pdp-was-now-sale-price):
  //
  //   Colour-only  → ?color=JJ8UTXX           (no pid; product is still the master)
  //   Colour+size  → ?color=JJ8UTXX&pid=…M    (pid present; product switches to standalone
  //                                              variant which lacks tieredPrices reliably)
  //
  // Strategy: keep the master product's variants[] as the authoritative tieredPrices source.
  // Filter them by pid (exact) or colour (set) from the URL, then call getPriceData on the
  // scoped result. This is overridden into renderHeader so the base ProductView's own
  // getPriceData call (which reads the standalone variant and loses tieredPrices) is bypassed.
  const masterProductRef = useRef<SfccProduct | null>(null);
  useEffect(() => {
    // Guard matches exactly what the memo reads from the cache: id (for the
    // cachedMasterMatchesCurrent check) and variants[] (for the filter). A partial SFCC
    // response that satisfies type.master but lacks either field is not useful — skip it
    // rather than writing a cache entry that would fall through to the deep-link fallback
    // one guard too late.
    if (productResponse?.type?.master && productResponse.id && productResponse.variants?.length) {
      masterProductRef.current = productResponse;
    }
  }, [productResponse]);

  const urlPid = urlParams.get('pid') ?? undefined;
  const variantScopedPriceData = useMemo(
    () => selectVariantScopedPriceData(product, masterProductRef.current, urlPid, urlColour),
    // Re-runs when the fetched product changes (standalone variant arrives) or the URL
    // selection changes — both are signals the displayed price must update.
    // masterProductRef is a ref so it is intentionally absent from deps.

    [urlPid, urlColour, product],
  );

  // True while keepPreviousData holds stale product data during a variant re-fetch (size
  // selection). The fetched product id hasn't caught up with the URL yet, so any price
  // derived from the old product is unreliable — suppress it entirely until the fetch
  // settles rather than showing a briefly-incorrect Was/Now figure.
  const isPriceStale = requestedProductId !== product?.id;

  // This page uses the `primaryCategoryId` to retrieve the category data. This attribute
  // is only available on `master` products. Since a variation will be loaded once all the
  // attributes are selected (to get the correct inventory values), the category information
  // is overridden. This will allow us to keep the initial category around until a different
  // master product is loaded.
  useEffect(() => {
    if (category) {
      setPrimaryCategory(category);
    }
  }, [category]);

  /**************** Product Variant ****************/
  useEffect(() => {
    if (!variant) {
      return;
    }
    // update the variation attributes parameter on
    // the url accordingly as the variant changes
    const updatedUrl = rebuildPathWithParams(`${location.pathname}${location.search}`, {
      pid: variant?.productId,
    });
    history.replace(updatedUrl);
  }, [variant]);

  /**************** Wishlist ****************/
  const { data: wishlist, isLoading: isWishlistLoading } = useWishList();
  const createCustomerProductListItem = useShopperCustomersMutation('createCustomerProductListItem');

  // Derived at render time so ProductView can show the solid heart icon without needing
  // updateWishlist as a proxy. Matches the same check inside handleAddToWishlist.
  const isInWishlist = Boolean(
    wishlist?.customerProductListItems?.find(
      (i: { productId?: string }) => i.productId === variant?.productId || i.productId === product?.id,
    ),
  );

  const handleAddToWishlist = (product: SfccProduct, variant: SfccVariant, quantity: number) => {
    const isItemInWishlist = wishlist?.customerProductListItems?.find(
      (i: { productId?: string }) => i.productId === variant?.productId || i.productId === product?.id,
    );

    if (!isItemInWishlist) {
      createCustomerProductListItem.mutate(
        {
          parameters: {
            listId: wishlist.id,
            // SDK param widening — `useCustomerId` returns `string | null`; this branch is
            // only reachable once a wishlist has loaded, which requires a customer.
            customerId: customerId as string,
          },
          body: {
            // NOTE: API does not respect quantity, it always adds 1
            quantity,
            productId: variant?.productId || product?.id,
            public: false,
            priority: 1,
            type: 'product',
          },
        },
        {
          onSuccess: () => {
            toast({
              title: formatMessage(TOAST_MESSAGE_ADDED_TO_WISHLIST, { quantity: 1 }),
              status: 'success',
              action: (
                // it would be better if we could use <Button as={Link}>
                // but unfortunately the Link component is not compatible
                // with Chakra Toast, since the ToastManager is rendered via portal
                // and the toast doesn't have access to intl provider, which is a
                // requirement of the Link component.
                <Button variant="link" onClick={() => navigate('/account/wishlist')}>
                  {formatMessage(TOAST_ACTION_VIEW_WISHLIST)}
                </Button>
              ),
            });
          },
          onError: () => {
            showError();
          },
        },
      );
    } else {
      toast({
        title: formatMessage(TOAST_MESSAGE_ALREADY_IN_WISHLIST),
        status: 'info',
        action: (
          <Button variant="link" onClick={() => navigate('/account/wishlist')}>
            {formatMessage(TOAST_ACTION_VIEW_WISHLIST)}
          </Button>
        ),
      });
    }
  };

  /**************** Add To Cart ****************/
  const showToast = useToast();
  const showError = (errorMessage?: unknown) => {
    const errorText = typeof errorMessage === 'string' ? errorMessage : formatMessage(API_ERROR_MESSAGE);

    showToast({
      title: errorText,
      status: 'error',
    });
  };

  const [pickupInStoreMap, setPickupInStoreMap] = useState<Record<string, boolean>>({});

  const handlePickupInStoreChange = (productId: string, checked: boolean) => {
    setPickupInStoreMap((prev) => ({
      ...prev,
      [productId]: checked,
    }));
  };

  const handleAddToCart = async (productSelectionValues: ProductSelectionValue[] = []) => {
    try {
      let productItems: BasketLineItem[] = productSelectionValues.map((item) => {
        const { variant, quantity } = item;
        // Use variant if present, otherwise use the main product
        const prod = variant || item.product || product;
        return {
          productId: prod?.productId || prod?.id, // productId for variant, id for product
          price: prod?.price,
          quantity,
        };
      });
      // Add inventory IDs for pickup items using the hook helper
      productItems = addInventoryIdsToPickupItems(productItems, pickupInStoreMap, selectedStore);
      // Defensive check: This block ensures that if, for any reason, pickup is selected for a product but no store (inventoryId) is set,
      // we show an error. With the current UI logic, this should never be reached, but it guards against unexpected state.
      if (
        productItems.some(
          // Index-type assertion, not one of the "SDK param widening" casts described above:
          // `pickupInStoreMap` is this page's own `Record<string, boolean>` state, and
          // `item.productId || item.id` is `string | undefined` on `BasketLineItem`, which
          // TypeScript rejects as an index (TS2538). Every item here was built above from
          // `prod?.productId || prod?.id`, and a key that is absent reads as `undefined` —
          // falsy, exactly as the base file's untyped index behaves.
          (item) => item.inventoryId === undefined && pickupInStoreMap[(item.productId || item.id) as string],
        )
      ) {
        showError(
          formatMessage({
            id: 'product_view.error.no_store_selected_for_pickup',
            defaultMessage: 'No valid store or inventory found for pickup',
          }),
        );
        return;
      }

      // Check if any products have pickup selected
      const hasAnyPickupSelected = hasPickupItems(productSelectionValues, pickupInStoreMap, product);

      const currentShippingMethodIsPickup = isPickupMethod(basket?.shipments?.[0]?.shippingMethod);
      // Only perform the check if the basket exists and has at least one item
      if (!multishipEnabled && basket && basket.productItems?.length > 0) {
        if (hasAnyPickupSelected && !currentShippingMethodIsPickup) {
          throw new Error(
            formatMessage({
              id: 'product_view.error.select_ship_to_address',
              defaultMessage: "Select 'Ship to Address' to match the delivery method for the items in your cart.",
            }),
          );
        }
        if (!hasAnyPickupSelected && currentShippingMethodIsPickup) {
          throw new Error(
            formatMessage({
              id: 'product_view.error.select_pickup_in_store',
              defaultMessage: "Select 'Pick Up in Store' to match the delivery method for the items in your cart.",
            }),
          );
        }
      }

      // Fetch and assign a suitable shipment for product items
      const targetShipmentId = await getShipmentIdForItems(hasAnyPickupSelected, selectedStore);

      if (targetShipmentId) {
        productItems = productItems.map((item) => ({
          ...item,
          shipmentId: targetShipmentId,
        }));
      }

      const basketResponse = await addItemToNewOrExistingBasket(productItems);

      // Configure shipping method for default shipment based on pickup selection
      await updateDefaultShipmentIfNeeded(basketResponse, targetShipmentId, hasAnyPickupSelected, selectedStore);

      const productItemsForEinstein = productSelectionValues.map(({ product, variant, quantity }) => ({
        product,
        productId: variant?.productId || product?.id,
        price: variant?.price || product?.price,
        quantity,
      }));
      einstein.sendAddToCart(productItemsForEinstein);

      return productSelectionValues;
    } catch (error) {
      // `catch` binds `unknown` under strict mode, and a thrown non-Error has no `.message`,
      // so narrow instead of asserting. Behaviour is unchanged — the previous
      // `(error as Error).message` also yielded `undefined` for a non-Error — but this was the
      // only `as` in this file without the inline reason typescript.md requires.
      showError(error instanceof Error ? error.message : undefined);
    }
  };

  /**************** Product Set/Bundles Handlers ****************/
  const handleChildProductValidation = useCallback(() => {
    // Run validation for all child products. This will ensure the error
    // messages are shown.
    Object.values(childProductRefs.current).forEach(({ validateOrderability }) => {
      validateOrderability({ scrollErrorIntoView: false });
    });

    // Using ot state for which child products are selected, scroll to the first
    // one that isn't selected and requires a variant selection.
    const selectedProductIds = Object.keys(childProductSelection);
    const firstUnselectedProduct = product?.childProducts?.find(
      ({ product: childProduct }: { product: SfccProduct }) => {
        // Skip validation for standard products (no variations)
        if (childProduct.type?.item) {
          return false;
        }
        return !selectedProductIds.includes(childProduct.id);
      },
    )?.product;

    if (firstUnselectedProduct) {
      // Get the reference to the product view and scroll to it.
      const { ref } = childProductRefs.current[firstUnselectedProduct.id];

      // Deviation from the base file: `?.` on `ref`, required by strictNullChecks —
      // `ChildProductRef.ref` is typed `HTMLDivElement | null`. The base reads
      // `ref.scrollIntoView` unguarded and throws when the child view has not mounted; ours
      // short-circuits and returns `false`. The unguarded call inside the block is reached
      // only once this guard has passed.
      if (ref?.scrollIntoView) {
        ref.scrollIntoView({
          behavior: 'smooth',
          block: 'end',
        });
      }

      return false;
    }

    return true;
  }, [product, childProductSelection]);

  /**************** Product Set Handlers ****************/
  // 1. Gather the selected child products from state.
  // 2. Call handleAddToCart with the selected products.
  // 3. The add-to-cart modal will be opened in handleAddToCart.
  const handleProductSetAddToCart = () => {
    // Get all the selected products, and pass them to the addToCart handler which
    // accepts an array.
    const productSelectionValues = Object.values(childProductSelection);
    return handleAddToCart(productSelectionValues);
  };

  /**************** Product Bundle Handlers ****************/
  // Top level bundle does not have variants
  const handleProductBundleAddToCart = async ([{ quantity: selectedQuantity }]: Array<{ quantity?: number }>) => {
    try {
      const childProductSelections = Object.values(childProductSelection);
      // Check if any products have pickup selected (including main product and bundle items)
      const bundleSelectionValues = [{ product, variant: null, selectedQuantity }, ...childProductSelections];
      const hasAnyPickupSelected = hasPickupItems(bundleSelectionValues, pickupInStoreMap, product);

      // Check for delivery method conflicts before adding to cart
      if (!multishipEnabled && basket && basket.productItems?.length > 0) {
        const currentShippingMethod = basket?.shipments?.[0]?.shippingMethod;
        const currentShippingMethodIsPickup = isPickupMethod(currentShippingMethod);

        // If there's no shipping method, treat it as non-pickup (ship to address)
        if (hasAnyPickupSelected && (!currentShippingMethod || !currentShippingMethodIsPickup)) {
          throw new Error(
            formatMessage({
              id: 'product_view.error.select_ship_to_address',
              defaultMessage: "Select 'Ship to Address' to match the delivery method for the items in your cart.",
            }),
          );
        } else if (!hasAnyPickupSelected && currentShippingMethod && currentShippingMethodIsPickup) {
          throw new Error(
            formatMessage({
              id: 'product_view.error.select_pickup_in_store',
              defaultMessage: "Select 'Pick Up in Store' to match the delivery method for the items in your cart.",
            }),
          );
        }
      }

      let productItems: BasketLineItem[] = [
        {
          productId: product.id,
          price: product.price,
          quantity: selectedQuantity,
          // The add item endpoint in the shopper baskets API does not respect variant selections
          // for bundle children, so we have to make a follow up call to update the basket
          // with the chosen variant selections
          bundledProductItems: childProductSelections.map((child) => {
            return {
              productId: child.variant?.productId || child.product?.id,
              quantity: child.quantity,
            };
          }),
        },
      ];

      // Add inventory IDs for pickup items using the hook helper
      productItems = addInventoryIdsToPickupItems(productItems, pickupInStoreMap, selectedStore);

      // Fetch and assign a suitable shipment for product items
      const targetShipmentId = await getShipmentIdForItems(hasAnyPickupSelected, selectedStore);

      if (targetShipmentId) {
        productItems = productItems.map((item) => ({
          ...item,
          shipmentId: targetShipmentId,
        }));
      }

      const res = await addItemToNewOrExistingBasket(productItems);

      const bundleChildMasterIds = childProductSelections.map((child) => {
        return child.product.id;
      });

      // since the returned data includes all products in basket
      // here we compare list of productIds in bundleProductItems of each productItem to filter out the
      // current bundle that was last added into cart
      // Deviation from the base file: `?.` on `productItems`. The SDK types it optional; the
      // base file assumes the just-created basket always has line items.
      const currentBundle = res.productItems?.find((productItem: SfccProduct) => {
        if (!productItem.bundledProductItems?.length) return;
        const bundleChildIds = productItem.bundledProductItems?.map((item: { productId?: string }) => {
          // seek out the bundle child that still uses masterId as product id
          return item.productId;
        });
        return bundleChildIds.every((id: string) => bundleChildMasterIds.includes(id));
      });

      const itemsToBeUpdated = getUpdateBundleChildArray(currentBundle, childProductSelections);

      if (itemsToBeUpdated.length) {
        // make a follow up call to update child variant selection for product bundle
        // since add item endpoint doesn't currently consider product bundle child variants
        await updateItemsInBasketMutation.mutateAsync({
          // SDK param widening — `method` is a real, honoured option on the v2 baskets
          // mutation (the base file relies on it to send PATCH rather than the default), but
          // it is absent from the published mutation-parameter type. Dropping it would change
          // the HTTP verb, so the argument is asserted instead.
          method: 'PATCH',
          parameters: {
            // `res` is the basket this call just wrote to.
            basketId: res.basketId as string,
          },
          body: itemsToBeUpdated,
        } as Parameters<typeof updateItemsInBasketMutation.mutateAsync>[0]);
      }

      // Configure shipping method based on pickup selection
      await updateDefaultShipmentIfNeeded(res, targetShipmentId, hasAnyPickupSelected, selectedStore);

      einstein.sendAddToCart(productItems);

      return childProductSelections;
    } catch (error) {
      showError(error);
    }
  };

  // SFCC-83/84 build plan step A4, revised 2026-09-08 — Einstein is "Not Deployed" on every real
  // Zimmermann site, so `markProductViewed` (this browser's own interim view-history stand-in)
  // is obtained here, alongside the Einstein hooks above, and called from the existing Einstein
  // effect immediately below.
  const { markProductViewed } = useRecentlyViewedHistory();

  /**************** Einstein ****************/
  useEffect(() => {
    if (product && product.type.set) {
      einstein.sendViewProduct(product);
      dataCloud.sendViewProduct(product);
      const childrenProducts = product.setProducts;
      childrenProducts.map((child: SfccProduct) => {
        try {
          einstein.sendViewProduct(child);
        } catch (err) {
          logger.error('Einstein sendViewProduct error', {
            namespace: 'ProductDetail.useEffect',
            additionalProperties: { error: err, child },
          });
        }
        activeData.sendViewProduct(category, child, 'detail');
        dataCloud.sendViewProduct(child);
      });
    } else if (product) {
      try {
        einstein.sendViewProduct(product);
      } catch (err) {
        logger.error('Einstein sendViewProduct error', {
          namespace: 'ProductDetail.useEffect',
          additionalProperties: { error: err, product },
        });
      }
      activeData.sendViewProduct(category, product, 'detail');
      dataCloud.sendViewProduct(product);
    }
    if (product) markProductViewed(product.id);
  }, [product]);

  /**************** SFCC-89 — static product information ****************/
  // This formatter never executes. The page reads only `modelInfo` and `styleCode` off the mapper
  // — the meta block below the accordions carries no price at all (`ZimmProductMeta`'s props are
  // `modelInfo`/`styleCode`) — so `null` is passed for `priceData` below and the mapper's price
  // branch (`typeof priceData?.currentPrice === 'number'`) is always false. It exists solely to
  // satisfy `selectPdpProductInfo`'s required `formatPrice` parameter, which stays required so
  // that module can hold its own contract of being free of react-intl.
  //
  // `partials/staticProductHeader.tsx` declares an identical formatter and that one IS live. The
  // two cannot disagree on a rendered price, because only one of them ever formats anything.
  const formatPrice = (amount: number, priceCurrency: string) =>
    formatNumber(amount, { style: 'currency', currency: priceCurrency });

  // Model copy and the style code are not part of the content group: the design places them at
  // the foot of the column, below the accordions, so the page positions them itself.
  const staticInfo = selectPdpProductInfo(product, null, product?.currency ?? '', formatPrice);

  /**************** SFCC-736/195 — Details & Care drawer + PDP trigger links ****************/
  // Placeholder for the three tabs and the Find in Boutique drawer that have no real content yet
  // (Size Guide/Shipping & Returns/Assistance are Contentful-managed with no content model
  // scoped yet — SFCC-102/267; Find in Boutique is SFCC-297, no ticket started). Reuses the base
  // accordion's own message id so any existing translation for the string is not orphaned.
  const comingSoon = (
    <FormattedMessage defaultMessage="Coming Soon" id="product_detail.accordion.message.coming_soon" />
  );

  // SFCC-898 — the drawer's width tier must switch with the viewport (mobile <768px, tablet
  // 768–1279px = 80%, desktop >=1280px = 50%; see zimmDrawer.css.ts's WIDTH_TABLET/WIDTH_LARGE,
  // Figma's "Tablet"/"Desktop Large" sizes), matching the grid's own md/xl breakpoints
  // (gridSystem.ts). A hardcoded `size` prop pins the drawer to one variant's CSS at every
  // viewport, which was the root cause of SFCC-898's width defects. `?? 'mobile'` covers
  // SSR/first-paint, before useBreakpointValue can resolve.
  const pdpDrawerSize: ZimmDrawerSize =
    useBreakpointValue<ZimmDrawerSize>({
      base: 'mobile',
      md: 'tablet',
      xl: 'large',
    }) ?? 'mobile';

  // One ZimmPdpDrawer instance for the four real drawer-menu tabs (matches Figma node
  // 40000307:14062's `pdp/drawer/header` menu exactly — Find in Boutique is not one of them).
  // `resetDataOnClose: false` — ZimmPdpDrawer below is keyed on `activePdpTabId` to force a
  // remount when reopened on a different tab (see that prop's own doc comment); the default
  // reset-to-null-on-close changes that key in the same render `isOpen` flips to false, which
  // made React unmount the drawer immediately instead of letting Chakra's close transition play
  // (SFCC-898 — close never animated). Keeping the last id past close leaves the key stable
  // through the close animation; it still changes correctly on the next open with a new tab.
  const {
    isOpen: isPdpDrawerOpen,
    data: activePdpTabId,
    onOpen: openPdpDrawerAtTab,
    onClose: closePdpDrawer,
  } = useModalState<string>({ resetDataOnClose: false });

  const pdpDrawerTabs: ZimmPdpDrawerTab[] = [
    {
      id: 'details-and-care',
      label: formatMessage({
        id: 'product_detail.drawer_trigger.label.details_and_care',
        defaultMessage: 'Details & Care',
      }),
      content: (
        <DetailsAndCareContent
          displayName={staticInfo?.name ?? ''}
          longDescription={staticInfo?.description}
          careInstructions={staticInfo?.careInstructions}
          styleCode={staticInfo?.styleCode}
        />
      ),
    },
    {
      id: 'size-guide',
      label: formatMessage({
        id: 'product_detail.drawer_trigger.label.size_guide',
        defaultMessage: 'Size Guide',
      }),
      content: comingSoon,
    },
    {
      id: 'find-your-size',
      label: formatMessage({
        id: 'product_detail.drawer_trigger.label.find_your_size',
        defaultMessage: 'Find My Size',
      }),
      content: comingSoon,
    },
    {
      id: 'shipping-and-returns',
      label: formatMessage({
        id: 'product_detail.drawer_trigger.label.shipping_and_returns',
        defaultMessage: 'Shipping & Returns',
      }),
      content: comingSoon,
    },
    {
      id: 'assistance',
      label: formatMessage({
        id: 'product_detail.drawer_trigger.label.assistance',
        defaultMessage: 'Assistance',
      }),
      content: comingSoon,
    },
    {
      id: 'environmental-qualities',
      label: formatMessage({
        id: 'product_detail.drawer_trigger.label.environmental_qualities',
        defaultMessage: 'Environmental Qualities',
      }),
      content: comingSoon,
    },
  ];

  // Find in Boutique (SFCC-297) is not part of the drawer's own tab menu — a separate, untabbed
  // ZimmDrawer instance, per Figma (the link sits outside the `pdp/drawer` "Drawer" trigger-row
  // component entirely). No real content yet either — same placeholder.
  const {
    isOpen: isBoutiqueDrawerOpen,
    onOpen: openBoutiqueDrawerRaw,
    onClose: closeBoutiqueDrawer,
  } = useModalState<null>();
  const openBoutiqueDrawer = () => openBoutiqueDrawerRaw(null);

  const findInBoutiqueLabel = formatMessage({
    id: 'product_detail.drawer_trigger.label.find_in_boutique',
    defaultMessage: 'Find in Boutique',
  });

  const pdpDrawerAriaLabel = formatMessage({
    id: 'product_detail.drawer.aria_label',
    defaultMessage: 'Product information',
  });

  return (
    <Box className="sf-product-detail-page" data-testid="product-details-page">
      <Heading as="h1" srOnly>
        {product?.name ?? (
          <FormattedMessage defaultMessage="Product Details" id="product_detail.title.product_details" />
        )}
      </Heading>
      <Helmet>
        <title>{product?.pageTitle}</title>
        {product?.pageMetaTags?.length > 0 &&
          product.pageMetaTags.map(({ id, value }: { id: string; value: string }) => (
            <meta name={id} content={value} key={id} />
          ))}
        {/* Fallback for description if not included in pageMetaTags */}
        {!product?.pageMetaTags?.some((tag: { id: string }) => tag.id === 'description') &&
          product?.pageDescription && <meta name="description" content={product.pageDescription} />}
      </Helmet>

      <Stack spacing={0}>
        {/*
         * SFCC-731 — full-bleed: no page-level maxWidth/padding from PageContainer itself, so
         * ProductView's own Flex (gap/pr confirmed against Figma) controls the gallery/content
         * column layout. `marginX` here additionally cancels the *sitewide* `#app-main`
         * padding — `theme/globalStyles.ts`'s `zimmAppMain` (Tier 2, applies to every page for
         * header/footer/main alignment; deliberately not touched here, same
         * negative-margin-to-opt-out technique `RecommendedProducts`'s `mx` already uses below
         * for its own edge-to-edge carousels). Matches `zimmAppMain`'s own breakpoint (`xl`,
         * not this file's `lg`) and its exact --zimm-grid-margin-mobile/-desktop values, so the
         * cancellation is exact at every width, not just at our own layout breakpoint —
         * `APP_MAIN_BLEED_MX` (`app/constants`) is this exact same cancellation, already shared.
         */}
        <PageContainer boxed={false} marginX={APP_MAIN_BLEED_MX}>
          {isProductASet || isProductABundle ? (
            <Fragment>
              <Island hydrateOn={'visible'}>
                <ProductView
                  product={product}
                  category={primaryCategory?.parentCategoryTree || []}
                  addToCart={isProductASet ? handleProductSetAddToCart : handleProductBundleAddToCart}
                  addToWishlist={handleAddToWishlist}
                  isInWishlist={isInWishlist}
                  isProductLoading={isProductLoading}
                  isBasketLoading={isBasketLoading}
                  isWishlistLoading={isWishlistLoading}
                  validateOrderability={handleChildProductValidation}
                  childProductOrderability={childProductOrderability}
                  setSelectedBundleQuantity={setSelectedBundleQuantity}
                  selectedBundleParentQuantity={selectedBundleQuantity}
                  pickupInStore={!!pickupInStoreMap[product?.id]}
                  setPickupInStore={(checked: boolean) => product && handlePickupInStoreChange(product.id, checked)}
                  onOpenStoreLocator={onOpenStoreLocator}
                  showDeliveryOptions={false}
                />
              </Island>

              <hr />

              {
                // Render the child products
                product?.childProducts?.map(
                  ({ product: childProduct, quantity: childQuantity }: { product: SfccProduct; quantity: number }) => (
                    <Box key={childProduct.id} data-testid="child-product">
                      <ProductView
                        // Do not use an arrow function as we are manipulating the functions scope.
                        ref={function (this: ProductViewRefScope, ref: ChildProductRef['ref']) {
                          // Assign the "set" scope of the ref, this is how we access the internal
                          // validation.
                          childProductRefs.current[childProduct.id] = {
                            ref,
                            validateOrderability: this.validateOrderability,
                          };
                        }}
                        product={childProduct}
                        isProductPartOfSet={isProductASet}
                        isProductPartOfBundle={isProductABundle}
                        childOfBundleQuantity={childQuantity}
                        selectedBundleParentQuantity={selectedBundleQuantity}
                        addToCart={
                          isProductASet
                            ? (productSelectionValues: ProductSelectionValue[]) =>
                                handleAddToCart(productSelectionValues)
                            : null
                        }
                        addToWishlist={isProductASet ? handleAddToWishlist : null}
                        onVariantSelected={(product: SfccProduct, variant: SfccVariant, quantity: number) => {
                          if (quantity) {
                            setChildProductSelection((previousState) => ({
                              ...previousState,
                              [product.id]: {
                                product,
                                variant,
                                quantity: isProductABundle ? childQuantity : quantity,
                              },
                            }));
                          } else {
                            const selections = {
                              ...childProductSelection,
                            };
                            delete selections[product.id];
                            setChildProductSelection(selections);
                          }
                        }}
                        isProductLoading={isProductLoading}
                        isBasketLoading={isBasketLoading}
                        isWishlistLoading={isWishlistLoading}
                        setChildProductOrderability={setChildProductOrderability}
                        pickupInStore={!!pickupInStoreMap[childProductSelection[childProduct?.id]?.variant?.productId]}
                        setPickupInStore={(checked: boolean) =>
                          childProduct &&
                          handlePickupInStoreChange(
                            childProductSelection[childProduct?.id]?.variant?.productId,
                            checked,
                          )
                        }
                        onOpenStoreLocator={onOpenStoreLocator}
                        showDeliveryOptions={false}
                      />
                      <InformationAccordion product={childProduct} />

                      <Box display={['none', 'none', 'none', 'block']}>
                        <hr />
                      </Box>
                    </Box>
                  ),
                )
              }
            </Fragment>
          ) : (
            <Fragment>
              <Island hydrateOn={'visible'}>
                <ProductView
                  product={product}
                  category={primaryCategory?.parentCategoryTree || []}
                  renderVariationAttribute={(attr) => {
                    if (attr.id !== SFCC_COLOUR_ATTRIBUTE_ID) return undefined;
                    // When useDerivedProduct runs in controlled mode (size selected in local state),
                    // SFCC's useVariationAttributes sets href:null on every value. We reconstruct
                    // the href from the current URL — preserving existing params and swapping only
                    // the colour — so swatches remain navigable after a size is picked.
                    const values = (attr.values ?? []).map((v: SfccSwatchAttrValue) => {
                      const params = new URLSearchParams(location.search);
                      // Clear the size-variant pid so the new colour loads the master product,
                      // not the previous colour's variant. Without this, requestedProductId
                      // keeps fetching the old variant and the colour disagrees with what's shown.
                      params.delete('pid');
                      params.set(SFCC_COLOUR_ATTRIBUTE_ID, v.value ?? '');
                      return {
                        value: v.value ?? '',
                        name: v.name ?? v.value ?? '',
                        imageUrl: v.image?.disBaseLink || v.image?.link,
                        href: `${location.pathname}?${params.toString()}`,
                        orderable: v.orderable ?? true,
                      };
                    });

                    // SFCC-708 — append related-colour swatches from the SCAPI-enriched
                    // c_relatedSwatches field. The backend already filters out invalid and
                    // offline products, so every item here is safe to render. Each swatch
                    // links to a different master product via a full page reload (forceReload).
                    // `c_relatedSwatches` is a Zimmermann SCAPI attribute absent from the SDK
                    // types — the cast is safe because the backend guarantees this shape.
                    const relatedSwatches = buildRelatedSwatches(
                      (product?.c_relatedSwatches ?? []) as RelatedSwatch[],
                      // Regional link prefixing fix (same class of bug as
                      // productListCardMapper.ts's PLP href): productUrlBuilder alone has no
                      // site/locale awareness, so its output is run through useSafeHref() before
                      // buildRelatedSwatches appends the colour query param.
                      (params) => buildHref(productUrlBuilder(params)),
                      SFCC_COLOUR_ATTRIBUTE_ID,
                    );
                    const allValues = [...values, ...relatedSwatches];
                    // Skeleton height approximates the rendered swatch group:
                    // label row (var(--zimm-scale-xl) = 24px) + gap (8px) + swatch row (48px).
                    return (
                      <Suspense fallback={<Skeleton height="80px" />}>
                        <ZimmColourSwatchGroup
                          values={allValues}
                          selectedValue={urlColour}
                          label={attr.name ?? 'Colour'}
                        />
                      </Suspense>
                    );
                  }}
                  renderHeader={(headerProps) => (
                    <StaticProductHeader
                      {...headerProps}
                      priceData={isPriceStale ? null : variantScopedPriceData ?? headerProps.priceData}
                      isPriceLoading={isPriceStale}
                    />
                  )}
                  addToCart={handleAddToCart}
                  addToWishlist={handleAddToWishlist}
                  isInWishlist={isInWishlist}
                  isProductLoading={isProductLoading}
                  isBasketLoading={isBasketLoading}
                  isWishlistLoading={isWishlistLoading}
                  childProductOrderability={childProductOrderability}
                  setChildProductOrderability={setChildProductOrderability}
                  setSelectedBundleQuantity={setSelectedBundleQuantity}
                  selectedBundleParentQuantity={selectedBundleQuantity}
                  pickupInStore={!!pickupInStoreMap[product?.id]}
                  setPickupInStore={(checked: boolean) => product && handlePickupInStoreChange(product.id, checked)}
                  onOpenStoreLocator={onOpenStoreLocator}
                  showDeliveryOptions={false}
                  footerLinks={
                    // `ZimmProductMeta` renders here, not in a separate Box below `<Island>` (where
                    // `InformationAccordion` used to share one with it) — that positioned it as a
                    // full-width block below the *whole* ProductView (both the image gallery and
                    // info columns), so it rendered flush left instead of inside the info column,
                    // a real bug Tim caught by comparing the running page against Figma. Its own
                    // recipe (`zimmProductMeta.css.ts`'s `SPACE_META_ROW`/`paddingTop`) already
                    // supplies the 28px gap from the trigger rows above it — nothing extra needed
                    // here for that hop.
                    <Box display="flex" flexDirection="column">
                      <PdpFooterLinks
                        triggers={pdpDrawerTabs.map(({ id, label }) => ({ id, label }))}
                        onTriggerClick={openPdpDrawerAtTab}
                        findInBoutiqueLabel={findInBoutiqueLabel}
                        onFindInBoutiqueClick={openBoutiqueDrawer}
                      />
                      <ZimmProductMeta modelInfo={staticInfo?.modelInfo} styleCode={staticInfo?.styleCode} />
                    </Box>
                  }
                  maxOrderQuantity={MAX_PURCHASE_QUANTITY}
                  basketProductItems={basket?.productItems ?? []}
                  showQuantityPicker={false}
                  showStockMessage={false}
                  showActionButtons={!product?.variationAttributes?.some((a: { id: string }) => a.id === 'size')}
                  onFindYourSizeClick={() => openPdpDrawerAtTab('find-your-size')}
                  onSizeGuideClick={() => openPdpDrawerAtTab('size-guide')}
                />

                <ZimmPdpDrawer
                  key={activePdpTabId ?? 'closed'}
                  isOpen={isPdpDrawerOpen}
                  onClose={closePdpDrawer}
                  size={pdpDrawerSize}
                  tabs={pdpDrawerTabs}
                  initialTabId={activePdpTabId ?? undefined}
                  ariaLabel={pdpDrawerAriaLabel}
                />
                <ZimmDrawer
                  isOpen={isBoutiqueDrawerOpen}
                  onClose={closeBoutiqueDrawer}
                  size="small"
                  aria-label={findInBoutiqueLabel}
                >
                  <Box padding="var(--zimm-scale-xl)">{comingSoon}</Box>
                </ZimmDrawer>
              </Island>
            </Fragment>
          )}
        </PageContainer>

        {/* Product Recommendations — stays contained, same padding/maxWidth layerStyle="page"
            provided before. */}
        <PageContainer boxed={true}>
          <Stack spacing={16}>
            {!isProductASet && (
              <Island hydrateOn={'visible'}>
                <RecommendedProducts
                  title={
                    <FormattedMessage
                      defaultMessage="Complete the Set"
                      id="product_detail.recommended_products.title.complete_set"
                    />
                  }
                  recommender={EINSTEIN_RECOMMENDERS.PDP_COMPLETE_SET}
                  products={[product]}
                  mx={PAGE_CONTENT_BLEED_MX}
                  shouldFetch={() => product?.id}
                />
              </Island>
            )}
            <Island hydrateOn={'visible'}>
              <RecommendedProducts
                title={
                  <FormattedMessage
                    defaultMessage="You might also like"
                    id="product_detail.recommended_products.title.might_also_like"
                  />
                }
                recommender={EINSTEIN_RECOMMENDERS.PDP_MIGHT_ALSO_LIKE}
                products={[product]}
                mx={PAGE_CONTENT_BLEED_MX}
                shouldFetch={() => product?.id}
              />
            </Island>

            <Island hydrateOn={'visible'}>
              <RecommendedProducts
                // The Recently Viewed recommender doesn't use `products`, so instead we
                // provide a key to update the recommendations on navigation.
                key={location.key}
                title={
                  <FormattedMessage
                    defaultMessage="Recently Viewed"
                    id="product_detail.recommended_products.title.recently_viewed"
                  />
                }
                recommender={EINSTEIN_RECOMMENDERS.PDP_RECENTLY_VIEWED}
                mx={PAGE_CONTENT_BLEED_MX}
              />
            </Island>
          </Stack>
        </PageContainer>
      </Stack>
    </Box>
  );
};

ProductDetail.getTemplateName = () => 'product-detail';

/*
 * The base file declares `ProductDetail.propTypes = {match: PropTypes.object}` purely as
 * documentation — the component takes no props and never reads `match`. The TypeScript
 * signature above expresses the same thing at compile time, so the runtime `prop-types`
 * declaration is not carried over.
 */

export default ProductDetail;

